{
  "schemaVersion": "0.2",
  "slug": "loading-bar",
  "name": "LoadingBar",
  "family": "E",
  "status": "experimental",
  "purpose": "Shows page-level loading progress as a thin bar pinned to the viewport start edge.",
  "scenarios": [
    "Indicate route transition progress",
    "Show initial data load",
    "Mirror long task progress"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": false,
      "description": "Progress 0-100; omit for indeterminate."
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the progress bar."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Determinate progress."
    },
    {
      "name": "indeterminate",
      "description": "Unknown duration; animated bar."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a loading bar for local component loading; use Spinner or Skeleton.",
    "Do not show determinate progress without a real measurable total."
  ],
  "a11y": {
    "role": "progressbar",
    "keyboard": [],
    "focus": "Not focusable; status announced via role.",
    "labeling": "aria-label names the loading process; aria-valuenow set when determinate.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Full viewport width at all breakpoints; pinned to the block-start edge.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "loading-bar",
    "states": [
      "default",
      "indeterminate"
    ],
    "intents": [
      "show-progress",
      "indicate-busy"
    ]
  }
}

import './styles.css'

export interface LoadingBarProps {
  value?: number
  label?: string
  className?: string
}

export function LoadingBar({ value, label = 'Loading', className }: LoadingBarProps) {
  const determinate = typeof value === 'number'
  const classes = ['cu-loading-bar', determinate ? '' : 'cu-loading-bar--indeterminate', className]
    .filter(Boolean)
    .join(' ')
  return (
    <div
      className={classes}
      role="progressbar"
      aria-label={label}
      aria-valuemin={determinate ? 0 : undefined}
      aria-valuemax={determinate ? 100 : undefined}
      aria-valuenow={determinate ? value : undefined}
      data-ai-role="loading-bar" data-ai-intent="show-progress"
      data-ai-state={determinate ? 'default' : 'indeterminate'}
    >
      <div
        className="cu-loading-bar__fill"
        style={determinate ? { inlineSize: `${Math.min(100, Math.max(0, value))}%` } : undefined}
      />
    </div>
  )
}

.cu-loading-bar {
  position: relative;
  inline-size: 100%;
  block-size: calc(var(--cu-space-1) / 2);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 12%, var(--cu-color-background-default));
  overflow: hidden;
}

.cu-loading-bar__fill {
  block-size: 100%;
  background: var(--cu-color-palette-brand);
  transition: inline-size 120ms linear;
}

.cu-loading-bar--indeterminate .cu-loading-bar__fill {
  inline-size: 40%;
  animation: cu-loading-bar-slide 1.2s ease-in-out infinite;
}

@keyframes cu-loading-bar-slide {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(250%);
  }
}

[dir='rtl'] .cu-loading-bar--indeterminate .cu-loading-bar__fill {
  animation-name: cu-loading-bar-slide-rtl;
}

@keyframes cu-loading-bar-slide-rtl {
  0% {
    transform: translateX(100%);
  }
  100% {
    transform: translateX(-250%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-loading-bar--indeterminate .cu-loading-bar__fill {
    animation: none;
  }
}
